// #5055f4 (6a9fc38e) — TC-VID-01: upload a video to own profile, autoplay, tap = pause, tap = resume, delete.
// The uploaded video is always deleted at the end (after-hook retries the delete). Airplane-mode case (TC-VID-02) stays manual.
// Layout points are taken from Pixel 6 screenshots .qa/screenshots/2026-10-26/verify/04-profile-with-video.png, 06-own-paused-1.png,
// 15-delete-confirm.png (the player and the media tiles have no accessibility ids).
// Gallery video: newest video whose duration label equals QA_VIDEO_DURATION (default "00:13"); use a clip with constant motion.
import assert from 'node:assert/strict';
import { startDriver, byText, goTab, tapXY, IS_IOS } from '../lib/session.js';

const DURATION = process.env.QA_VIDEO_DURATION || '00:13';
const UPLOAD_FAILED = ['ההעלאה נכשלה', 'לא הצלחנו להעלות את הקובץ'];

describe('Profile video: upload, autoplay, pause/resume, delete #5055f4 @ios @android @data', function () {
  let d; let win; let uploaded = false; let deleted = false;
  before(async () => { d = await startDriver(); win = await d.getWindowSize(); });

  /** Media tiles sit just above the "מאמרים" tab row: "+" tile on the right, the uploaded video to its left. */
  async function tilePoint(which) {
    await goTab(d, 'פרופיל');
    const tab = await byText(d, 'מאמרים');
    await tab.waitForDisplayed({ timeout: 15000 });
    const r = await tab.getElementRect(tab.elementId);
    return { x: win.width * (which === 'plus' ? 0.756 : 0.32), y: r.y - win.height * 0.0975 };
  }
  const shot = () => d.takeScreenshot();
  async function isPlaying(tries = 4) {
    for (let i = 0; i < tries; i++) { const a = await shot(); await d.pause(700); if (a !== await shot()) return true; }
    return false;
  }
  async function isStill(pairs = 3) {
    for (let i = 0; i < pairs; i++) { const a = await shot(); await d.pause(700); if (a !== await shot()) return false; }
    return true;
  }
  const center = () => tapXY(d, win.width / 2, win.height / 2);
  async function openOwnVideo() {
    const p = await tilePoint('video'); await tapXY(d, p.x, p.y); await d.pause(1500);
  }
  async function deleteOpenVideo() {
    if (IS_IOS) await (await byText(d, 'trash', true)).click().catch(() => tapXY(d, win.width * 0.917, win.height * 0.115));
    else await tapXY(d, win.width * 0.917, win.height * 0.115);   // trash icon, player top-right
    await (await byText(d, 'למחוק את התוכן הזה?')).waitForDisplayed({ timeout: 10000 });
    await (await byText(d, 'מחק')).click();
    await (await byText(d, 'התוכן נמחק', true)).waitForDisplayed({ timeout: 20000 });
    deleted = true;
  }

  after(async () => {
    if (!d) return;
    try { if (uploaded && !deleted) { await openOwnVideo(); await deleteOpenVideo(); } }
    finally { await d.deleteSession(); }
  });

  it('TC-VID-01: upload from gallery finishes without endless loader', async () => {
    const p = await tilePoint('plus'); await tapXY(d, p.x, p.y);
    if (!IS_IOS) {
      await (await byText(d, 'Videos')).click();
      let clip = await byText(d, DURATION, true);
      for (let i = 0; i < 6 && !(await clip.isDisplayed().catch(() => false)); i++) {
        await d.action('pointer', { parameters: { pointerType: 'touch' } }).move({ x: win.width / 2, y: win.height * 0.8 })
          .down().move({ duration: 400, x: win.width / 2, y: win.height * 0.35 }).up().perform();
        clip = await byText(d, DURATION, true);
      }
      await clip.click();
      await (await byText(d, 'Done')).click();
    } else {
      await (await byText(d, DURATION, true)).click();     // iOS picker — not verified on device yet
      await (await byText(d, 'Add', true)).click().catch(() => {});
    }
    uploaded = true;
    await d.pause(3000);
    const busy = IS_IOS ? '-ios class chain:**/XCUIElementTypeActivityIndicator' : 'android.widget.ProgressBar';
    await d.waitUntil(async () => (await d.$$(busy)).length === 0, { timeout: 120000, interval: 2000, timeoutMsg: 'upload loader still shown after 2 min' });
    for (const t of UPLOAD_FAILED) assert.equal(await (await byText(d, t, true)).isExisting(), false, `upload error "${t}"`);
  });

  it('TC-VID-01: opened video autoplays, tap pauses, second tap resumes', async () => {
    await openOwnVideo();
    assert.ok(await isPlaying(), 'video must start playing by itself');
    await center(); await d.pause(1200);
    assert.ok(await isStill(), 'tap while playing must pause');
    await center(); await d.pause(800);
    assert.ok(await isPlaying(), 'tap while paused must resume');
  });

  it('TC-VID-01: delete the uploaded video (cleanup) — "התוכן נמחק"', async () => {
    await deleteOpenVideo();
  });
});
